_PAL = None
_CACHE = {}


def forest_img(name, scale=2, remap=None, key=None):
  """remap: optional function (r, g, b) -> (r, g, b) used to tint the art (key names the tint for the cache)."""
  global _PAL
  k = (name, scale, key)
  s = _CACHE.get(k)
  if s is None:
    if _PAL is None:
      _PAL = [None] + [tuple(int(PAL[j + q:j + q + 2], 16) for q in (0, 2, 4)) for j in range(0, len(PAL), 6)]
    w, h, data = IMGS[name]
    raw = zlib.decompress(base64.b64decode(data))
    pal = _PAL if remap is None else [None] + [remap(c) for c in _PAL[1:]]
    try:                                        # fast path: 8-bit palette surface with colour 0 transparent
      s = pygame.image.frombuffer(raw, (w, h), 'P').copy()
      s.set_palette([(255, 0, 255)] + list(pal[1:]) + [(0, 0, 0)] * (255 - len(pal) + 1))
      s.set_colorkey(0)
      s = s.convert_alpha()
    except Exception:
      s = pygame.Surface((w, h), pygame.SRCALPHA)
      for p in range(w * h):
        v = raw[p]
        if v:
          s.set_at((p % w, p // w), pal[v] + (255,))
    if scale != 1:
      s = pygame.transform.scale(s, (int(w * scale), int(h * scale)))
    _CACHE[k] = s
  return s


def forest_size(name):
  return IMGS[name][0], IMGS[name][1]
